<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="javascript:void(0);" class="on">通联支付优惠列表</a>|					<a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Allinpay/discount_add')}','添加优惠',600,600,true,false,false,addbtn,'add',true);">添加优惠</a>				</ul>			</div>            <table class="search_table" width="100%">                <tr>                    <td style="width:60%;">                        <form action="{pigcms{:U('Shop/discount')}" method="get">                            <input type="hidden" name="c" value="Allinpay"/>                            <input type="hidden" name="a" value="discount"/>                            <if condition="$admin_area neq 3">                            <div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}" area_id="{pigcms{$_GET.area_id}" style="display:inline"></div>                            </if>　　　                            优惠类型: <select name="searchstatus">                                <option value="-1" <if condition="$_GET['searchstatus'] eq -1">selected="selected"</if>>全部</option>                                <option value="0" <if condition="$_GET['searchstatus'] eq 0">selected="selected"</if>>满减</option>                                <option value="1" <if condition="$_GET['searchstatus'] eq '1'">selected="selected"</if>>折扣</option>                                <option value="2" <if condition="$_GET['searchstatus'] eq '2'">selected="selected"</if>>随机立减</option>                            </select>　　　                            排序:<select name="sort">                                <option value="0" <if condition="$_GET['sort'] eq 0">selected="selected"</if>>最新添加</option>                                <option value="1" <if condition="$_GET['sort'] eq '1'">selected="selected"</if>>最早添加</option>                            </select>                           &nbsp; &nbsp;添加日期筛选：                            <input type="text" class="input-text" name="begin_time" style="width:80px;" id="begin_time"  value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                            <input type="text" class="input-text" name="end_time" style="width:80px;" id="end_time" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                            <input type="submit" value="查询" class="button"/>                        </form>                    </td>                </tr>            </table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col/>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th>编号</th>								<th>类别</th>								<th>满足金额</th>								<th>优惠方式</th>                                <th class="textcenter">开始时间</th>                                <th class="textcenter">结束时间</th>								<th>使用状态</th>								<th>使用区域</th>								<th>使用商家</th>								<th>使用卡BIN</th>								<th class="textcenter">明细</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($discount_list)">								<volist name="discount_list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>										<td><if condition="$vo['type'] eq 0">满减<elseif condition="$vo['type'] eq 1" />折扣<else />随机立减</if></td>										<td>{pigcms{$vo.reach_money}</td>										<td><if condition="$vo['type'] eq 0">减{pigcms{$vo.reduce_money}{pigcms{$config['Currency_txt']}<elseif condition="$vo['type'] eq 1" />{pigcms{$vo['discount']/10}折优惠<else />随机立减</if></td>                                        <td class="textcenter">{pigcms{$vo.startdate|date="Y-m-d H:i:s",###}</td>                                        <td class="textcenter">{pigcms{$vo.enddate|date="Y-m-d H:i:s",###}</td>										<td><if condition="$vo['status'] eq 1 AND $vo['state'] eq 1"><font color="green">已生效</font><elseif condition="$vo['status'] eq 1 AND $vo['state'] eq 0" /><font color="red">已结束</font><else/><font color="red">已关闭</font></if></td>										<td><if condition="$vo['use_area'] eq 1"><a href="{pigcms{:U('Allinpay/area',array('id' => $vo['id']))}">指定区域</a><else/><font color="green">所有区域可用</font></if></td>										<td><if condition="$vo['use_type'] eq 1"><a href="{pigcms{:U('Allinpay/merchant',array('id' => $vo['id']))}">指定商家</a><else/><font color="green">全部商家</font></if></td>										<td><if condition="$vo['card_limit'] eq 1"><a href="{pigcms{:U('Allinpay/card',array('id' => $vo['id']))}">指定卡BIN</a><else/><font color="green">全部卡BIN</font></if></td>										<td class="textcenter"><a href="{pigcms{:U('Allinpay/discount_use',array('id' => $vo['id']))}">查看使用明细</a></td>										<td class="textcenter"><a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Allinpay/discount_edit',array('id' => $vo['id'], 'frame_show'=>true))}','查看优惠信息',600,600,true,false,false,false,'detail',true);">查看</a> | <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('Allinpay/discount_edit',array('id' => $vo['id']))}','编辑优惠信息',600,600,true,false,false,editbtn,'edit',true);">编辑</a><if condition="$vo.status eq 0">| <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('delete_discount')}">删除</a></if></td>									</tr>								</volist>                                <tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="6">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div>        <script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script><include file="Public:footer"/>